import React, { useState } from 'react';

function Sidebar({ currentView, onViewChange, onLogout, userRole }) {
  const [isOpen, setIsOpen] = useState(true);

  const toggleSidebar = () => {
    setIsOpen(!isOpen);
  };

  const handleNavClick = (view) => {
    onViewChange(view);
    if (window.innerWidth <= 768) {
      setIsOpen(false);
    }
  };

  return (
    <>
      {/* Hamburger Menu */}
      <div 
        className="hamburger-menu"
        onClick={toggleSidebar}
        style={{
          left: isOpen ? '260px' : '20px',
          backgroundColor: isOpen ? 'white' : 'transparent'
        }}
      >
        <div className="hamburger-line"></div>
        <div className="hamburger-line"></div>
        <div className="hamburger-line"></div>
      </div>

      {/* Overlay */}
      {isOpen && (
        <div 
          className="sidebar-overlay"
          onClick={() => setIsOpen(false)}
        />
      )}

      {/* Sidebar */}
      <div className={`sidebar ${isOpen ? 'open' : ''}`}>
        <div className="sidebar-header">
          <h2>Task Manager</h2>
        </div>

        <nav className="sidebar-nav">
          <button
            className={`nav-item ${currentView === 'tasks' ? 'active' : ''}`}
            onClick={() => handleNavClick('tasks')}
          >
            📋 My Tasks
          </button>

          <button
            className={`nav-item ${currentView === 'preshift' ? 'active' : ''}`}
            onClick={() => handleNavClick('preshift')}
          >
            📄 Pre-Shift Form
          </button>

          {userRole === 'admin' && (
            <>
              <button
                className={`nav-item ${currentView === 'calendar' ? 'active' : ''}`}
                onClick={() => handleNavClick('calendar')}
              >
                📅 Calendar
              </button>

              <button
                className={`nav-item ${currentView === 'templates' ? 'active' : ''}`}
                onClick={() => handleNavClick('templates')}
              >
                ⚙️ Manage Templates
              </button>
            </>
          )}
        </nav>

        <div className="sidebar-footer">
          <button className="logout-btn" onClick={onLogout}>
            🚪 Logout
          </button>
        </div>
      </div>
    </>
  );
}

export default Sidebar;
